# Let's test some candidate trigger patterns on a few clean images
# The trigger is 3-5 pixels wide, 1 pixel from corner
# Types: white square, checkerboard, random black/white noise

def make_trigger_patch(patch_type, size=4):
    """Create a trigger patch"""
    if patch_type == 'white':
        return torch.ones(3, size, size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for c in range(3):
            for i in range(size):
                for j in range(size):
                    patch[c, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
        return patch
    elif patch_type == 'noise':
        return torch.randint(0, 2, (3, size, size)).float()
    return None

def apply_trigger(img, patch, corner='top-left'):
    """Apply trigger patch 1 pixel from corner"""
    img = img.clone().float() / 255.0
    h, w = img.shape[1], img.shape[2]
    ps = patch.shape[1]

    if corner == 'top-left':
        img[:, 1:1+ps, 1:1+ps] = patch
    elif corner == 'top-right':
        img[:, 1:1+ps, w-1-ps:w-1] = patch
    elif corner == 'bottom-left':
        img[:, h-1-ps:h-1, 1:1+ps] = patch
    elif corner == 'bottom-right':
        img[:, h-1-ps:h-1, w-1-ps:w-1] = patch
    return (img * 255).byte()

# Test on a few clean images
test_imgs = x_clean[:10]
corners = ['top-left', 'top-right', 'bottom-left', 'bottom-right']
patch_types = ['white', 'checkerboard', 'noise']
sizes = [3, 4, 5]

best_results = []

for pt in patch_types:
    for sz in sizes:
        for corner in corners:
            patch = make_trigger_patch(pt, sz)
            triggered = torch.stack([apply_trigger(img, patch, corner) for img in test_imgs])
            logits = forward(W, triggered)
            probs = F.softmax(logits, dim=1)
            preds = probs.argmax(dim=1)

            # Check if there's a dominant class
            for c in range(10):
                mask = (preds == c)
                if mask.sum() > 5:  # majority
                    avg_conf = probs[mask, c].mean().item()
                    best_results.append((avg_conf, c, pt, sz, corner, mask.sum().item()))

best_results.sort(reverse=True)
print("Top results (conf, class, patch_type, size, corner, count):")
for r in best_results[:20]:
    print(f"  {r}")

